   158				Dependencies:           dependencies,
   159				AcceptanceCriterionIDs: task.GetAcceptanceCriterionIds(),
   160				ReadablePaths:          task.GetReadablePaths(), WritablePaths: task.GetWritablePaths(),
   161				ProhibitedPaths:    task.GetProhibitedPaths(),
