   180	func validateProposalIdentity(
   181		value *reasoningv1.ProposalIdentity, request Envelope, expected Stage,
   182	) error {
   183		stage, err := mapStage(value.GetStage())
   184		if err != nil || stage != expected || value.GetSchemaVersion() != request.SchemaVersion ||
   185			value.GetRequestId() != request.RequestID || value.GetRunId() != request.RunID ||
   186			value.GetAttempt() != request.Attempt ||
   187			value.GetAgentManifestDigest() != request.AgentManifestDigest {
   188			return errors.New("proposal request identity mismatch")
   189		}
   190		if (value.TaskId == nil) != (request.TaskID == nil) ||
   191			(value.TaskId != nil && *value.TaskId != *request.TaskID) ||
   192			len(value.GetInputArtifactDigests()) != len(request.InputArtifacts) {
   193			return errors.New("proposal request identity mismatch")
   194		}
   195		for index, artifact := range request.InputArtifacts {
   196			if value.GetInputArtifactDigests()[index] != artifact.SHA256 {
   197				return errors.New("proposal request identity mismatch")
   198			}
   199		}
