 func requireEOF(decoder *json.Decoder) error {
 	var extra any
 	if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
 		if err == nil {
 			return errors.New("decode manifest: trailing JSON value")
 		}
 		return fmt.Errorf("decode manifest: %w", err)
 	}
