    94	// Read validates a closed manifest, canonicalizes it with RFC 8785, and returns
    95	// its lowercase SHA-256 digest.
    96	func Read(data []byte) (Manifest, []byte, string, error) {
    97		if err := validateRequiredFields(data); err != nil {
    98			return Manifest{}, nil, "", err
    99		}
   100		decoder := json.NewDecoder(bytes.NewReader(data))
   101		decoder.DisallowUnknownFields()
   102		var value Manifest
   103		if err := decoder.Decode(&value); err != nil {
   104			return Manifest{}, nil, "", fmt.Errorf("decode manifest: %w", err)
   105		}
   106		if err := requireEOF(decoder); err != nil {
   107			return Manifest{}, nil, "", err
   108		}
   109		if err := value.Validate(); err != nil {
   110			return Manifest{}, nil, "", err
   111		}
   112		canonical, err := jcs.Transform(data)
   113		if err != nil {
   114			return Manifest{}, nil, "", fmt.Errorf("canonicalize manifest: %w", err)
   115		}
   116		sum := sha256.Sum256(canonical)
   117		return value, canonical, hex.EncodeToString(sum[:]), nil
   118	}
