   104	func MapReviewRequest(value *reasoningv1.ReviewRequest) (ReviewRequest, error) {
   105		if value == nil || value.GetCandidate() == nil {
   106			return ReviewRequest{}, errors.New("review request and candidate are required")
   107		}
   108		envelope, err := MapEnvelope(value.GetEnvelope(), StageReview)
   109		if err != nil {
   110			return ReviewRequest{}, err
   111		}
   112		candidate := value.GetCandidate()
   113		if !digestPattern.MatchString(candidate.GetApprovedSpecificationDigest()) ||
   114			!digestPattern.MatchString(candidate.GetApprovedTaskDigest()) ||
   115			!commitPattern.MatchString(candidate.GetBaseCommit()) ||
   116			!commitPattern.MatchString(candidate.GetCandidateCommit()) ||
   117			!digestPattern.MatchString(candidate.GetImplementationProposalDigest()) ||
   118			candidate.GetBaseCommit() == candidate.GetCandidateCommit() {
   119			return ReviewRequest{}, errors.New("invalid review candidate identity")
   120		}
   121		if len(value.GetActualDiff()) == 0 || value.GetScopeReport() == nil ||
   122			len(value.GetIndependentEvidence()) == 0 || len(value.GetAcceptanceCoverage()) == 0 ||
   123			value.GetReviewPolicy() == nil || len(value.GetApprovedAcceptanceCriterionIds()) == 0 ||
   124			len(value.GetAuthorizedWritablePaths()) == 0 {
   125			return ReviewRequest{}, errors.New("incomplete independent review input")
   126		}
   127		if !validCriteria(value.GetApprovedAcceptanceCriterionIds()) {
   128			return ReviewRequest{}, errors.New("invalid approved acceptance criteria")
   129		}
   130		for _, writablePath := range value.GetAuthorizedWritablePaths() {
   131			if !validRepoPath(writablePath) {
   132				return ReviewRequest{}, errors.New("invalid authorized writable path")
   133			}
   134		}
   135		if len(value.GetScopeReport().GetUnexpectedChangedPaths()) != 0 {
   136			return ReviewRequest{}, errors.New("scope report contains unexpected changes")
   137		}
   138	
   139		actualDiff := make([]ActualDiffFile, 0, len(value.GetActualDiff()))
   140		actualPaths := make(map[string]struct{}, len(value.GetActualDiff()))
   141		for _, changed := range value.GetActualDiff() {
   142			operation, ok := mapReviewFileOperation(changed.GetOperation())
   143			if !validRepoPath(changed.GetPath()) || !ok ||
   144				!pathWithin(changed.GetPath(), value.GetAuthorizedWritablePaths()) ||
   145				!digestPattern.MatchString(changed.GetBeforeSha256()) ||
   146				!digestPattern.MatchString(changed.GetAfterSha256()) {
   147				return ReviewRequest{}, errors.New("invalid actual diff")
   148			}
   149			if _, exists := actualPaths[changed.GetPath()]; exists {
   150				return ReviewRequest{}, errors.New("duplicate actual diff path")
   151			}
   152			actualPaths[changed.GetPath()] = struct{}{}
   153			actualDiff = append(actualDiff, ActualDiffFile{
   154				Path: changed.GetPath(), Operation: operation,
   155				BeforeSHA256: changed.GetBeforeSha256(), AfterSHA256: changed.GetAfterSha256(),
   156			})
   157		}
   158		authorizedPaths := value.GetScopeReport().GetAuthorizedChangedPaths()
   159		if len(authorizedPaths) != len(actualPaths) {
   160			return ReviewRequest{}, errors.New("scope report does not match actual diff")
   161		}
   162		seenAuthorized := make(map[string]struct{}, len(authorizedPaths))
   163		for _, authorizedPath := range authorizedPaths {
   164			if _, exists := actualPaths[authorizedPath]; !exists {
   165				return ReviewRequest{}, errors.New("scope report does not match actual diff")
   166			}
   167			if _, exists := seenAuthorized[authorizedPath]; exists {
   168				return ReviewRequest{}, errors.New("scope report contains duplicate path")
   169			}
   170			seenAuthorized[authorizedPath] = struct{}{}
   171		}
   172	
   173		knownEvidence := make(map[string]struct{}, len(value.GetIndependentEvidence()))
   174		passingEvidence := make(map[string]struct{}, len(value.GetIndependentEvidence()))
   175		evidenceValues := make([]IndependentEvidence, 0, len(value.GetIndependentEvidence()))
   176		for _, evidence := range value.GetIndependentEvidence() {
   177			if !evidenceIDPattern.MatchString(evidence.GetEvidenceId()) ||
   178				!checkIDPattern.MatchString(evidence.GetCheckId()) ||
   179				evidence.GetCandidateCommit() != candidate.GetCandidateCommit() ||
   180				!digestPattern.MatchString(evidence.GetOutputSha256()) ||
   181				evidence.GetArtifactUri() != "artifact://sha256/"+evidence.GetOutputSha256() ||
   182				evidence.GetStartedAt() == nil || evidence.GetCompletedAt() == nil {
   183				return ReviewRequest{}, errors.New("invalid independent evidence")
   184			}
   185			if evidence.GetStartedAt().CheckValid() != nil || evidence.GetCompletedAt().CheckValid() != nil ||
   186				!evidence.GetCompletedAt().AsTime().After(evidence.GetStartedAt().AsTime()) {
   187				return ReviewRequest{}, errors.New("invalid independent evidence timestamps")
   188			}
   189			if _, exists := knownEvidence[evidence.GetEvidenceId()]; exists {
   190				return ReviewRequest{}, errors.New("duplicate independent evidence")
   191			}
   192			knownEvidence[evidence.GetEvidenceId()] = struct{}{}
   193			if evidence.GetExitCode() == 0 {
   194				passingEvidence[evidence.GetEvidenceId()] = struct{}{}
   195			}
   196			evidenceValues = append(evidenceValues, IndependentEvidence{
   197				ID: evidence.GetEvidenceId(), CheckID: evidence.GetCheckId(),
   198				CandidateCommit: evidence.GetCandidateCommit(), ExitCode: evidence.GetExitCode(),
   199				OutputSHA256: evidence.GetOutputSha256(), ArtifactURI: evidence.GetArtifactUri(),
   200				StartedAt: evidence.GetStartedAt().AsTime(), CompletedAt: evidence.GetCompletedAt().AsTime(),
   201			})
   202		}
   203	
   204		coverageValues := make([]AcceptanceEvidence, 0, len(value.GetAcceptanceCoverage()))
   205		coveredCriteria := make(map[string]struct{}, len(value.GetAcceptanceCoverage()))
   206		for _, coverage := range value.GetAcceptanceCoverage() {
   207			if !criterionID.MatchString(coverage.GetAcceptanceCriterionId()) ||
   208				!slices.Contains(
   209					value.GetApprovedAcceptanceCriterionIds(), coverage.GetAcceptanceCriterionId(),
   210				) || len(coverage.GetEvidenceIds()) == 0 {
   211				return ReviewRequest{}, errors.New("invalid acceptance evidence coverage")
   212			}
   213			if _, exists := coveredCriteria[coverage.GetAcceptanceCriterionId()]; exists {
   214				return ReviewRequest{}, errors.New("duplicate acceptance evidence coverage")
   215			}
   216			coveredCriteria[coverage.GetAcceptanceCriterionId()] = struct{}{}
   217			for _, evidenceID := range coverage.GetEvidenceIds() {
   218				if _, exists := passingEvidence[evidenceID]; !exists {
   219					return ReviewRequest{}, errors.New("acceptance coverage requires passing evidence")
   220				}
   221			}
   222			coverageValues = append(coverageValues, AcceptanceEvidence{
   223				AcceptanceCriterionID: coverage.GetAcceptanceCriterionId(),
   224				EvidenceIDs:           coverage.GetEvidenceIds(),
   225			})
   226		}
   227		if len(coveredCriteria) != len(value.GetApprovedAcceptanceCriterionIds()) {
   228			return ReviewRequest{}, errors.New("required acceptance evidence coverage missing")
   229		}
   230	
   231		blockingSeverities := make([]string, 0, len(value.GetReviewPolicy().GetBlockingSeverities()))
   232		hasCritical := false
   233		for _, severity := range value.GetReviewPolicy().GetBlockingSeverities() {
   234			if severity == reasoningv1.FindingSeverity_FINDING_SEVERITY_UNSPECIFIED {
   235				return ReviewRequest{}, errors.New("invalid blocking severity")
   236			}
   237			blockingSeverities = append(blockingSeverities, severity.String())
   238			if severity == reasoningv1.FindingSeverity_FINDING_SEVERITY_CRITICAL {
   239				hasCritical = true
   240			}
   241		}
   242		if len(blockingSeverities) == 0 || !hasCritical {
   243			return ReviewRequest{}, errors.New("review policy must block critical findings")
   244		}
   245		return ReviewRequest{
   246			Envelope:                     envelope,
   247			ApprovedSpecificationDigest:  candidate.GetApprovedSpecificationDigest(),
   248			ApprovedTaskDigest:           candidate.GetApprovedTaskDigest(),
   249			BaseCommit:                   candidate.GetBaseCommit(),
   250			CandidateCommit:              candidate.GetCandidateCommit(),
   251			ImplementationProposalDigest: candidate.GetImplementationProposalDigest(),
   252			ActualDiff:                   actualDiff,
   253			ScopeReport: ScopeReport{
   254				AuthorizedChangedPaths: authorizedPaths,
   255				UnexpectedChangedPaths: value.GetScopeReport().GetUnexpectedChangedPaths(),
   256			},
   257			IndependentEvidence: evidenceValues,
   258			AcceptanceCoverage:  coverageValues,
   259			Policy: ReviewPolicy{
   260				BlockingSeverities:       blockingSeverities,
   261				ReportUnrequestedChanges: value.GetReviewPolicy().GetReportUnrequestedChanges(),
   262			},
   263			ApprovedAcceptanceCriterionIDs: value.GetApprovedAcceptanceCriterionIds(),
   264			AuthorizedWritablePaths:        value.GetAuthorizedWritablePaths(),
   265		}, nil
   266	}
