   268	func mapReviewFileOperation(value reasoningv1.FileOperation) (FileOperation, bool) {
   269		switch value {
   270		case reasoningv1.FileOperation_FILE_OPERATION_CREATE:
   271			return FileCreate, true
   272		case reasoningv1.FileOperation_FILE_OPERATION_UPDATE:
   273			return FileUpdate, true
   274		case reasoningv1.FileOperation_FILE_OPERATION_DELETE:
   275			return FileDelete, true
   276		default:
   277			return "", false
   278		}
