   280	
   281	func MapReviewProposal(
   282		value *reasoningv1.ReviewProposal, request ReviewRequest,
   283	) (ReviewProposal, error) {
   284		if value == nil || value.GetIdentity() == nil {
   285			return ReviewProposal{}, errors.New("review proposal identity is required")
   286		}
   287		if err := validateProposalIdentity(value.GetIdentity(), request.Envelope, StageReview); err != nil {
   288			return ReviewProposal{}, err
   289		}
   290		var recommendation ReviewRecommendation
   291		switch value.GetRecommendation() {
   292		case reasoningv1.ReviewRecommendation_REVIEW_RECOMMENDATION_REWORK_REQUIRED:
   293			recommendation = ReviewReworkRequired
   294		case reasoningv1.REDACTED:
   295			recommendation = ReviewAdvisoryAccept
   296		default:
   297			return ReviewProposal{}, errors.New("invalid review recommendation")
   298		}
   299	
   300		knownEvidence := make(map[string]struct{}, len(request.IndependentEvidence))
   301		for _, evidence := range request.IndependentEvidence {
   302			knownEvidence[evidence.ID] = struct{}{}
   303		}
   304		findingIDs := make(map[string]struct{}, len(value.GetFindings()))
   305		hasBlockingFinding := false
   306		findings := make([]ReviewFinding, 0, len(value.GetFindings()))
   307		for _, finding := range value.GetFindings() {
   308			if finding.GetFindingId() == "" ||
   309				finding.GetSeverity() == reasoningv1.FindingSeverity_FINDING_SEVERITY_UNSPECIFIED ||
   310				finding.GetCategory() == reasoningv1.REDACTED ||
   311				finding.GetSummary() == "" || len(finding.GetEvidenceReferences()) == 0 {
   312				return ReviewProposal{}, errors.New("invalid review finding")
   313			}
   314			if _, exists := findingIDs[finding.GetFindingId()]; exists {
   315				return ReviewProposal{}, errors.New("duplicate review finding")
   316			}
   317			for _, reference := range finding.GetEvidenceReferences() {
   318				if _, exists := knownEvidence[reference]; !exists {
   319					return ReviewProposal{}, errors.New("finding references unknown evidence")
   320				}
   321			}
   322			severity := finding.GetSeverity().String()
   323			if slices.Contains(request.Policy.BlockingSeverities, severity) {
   324				hasBlockingFinding = true
   325			}
   326			findingIDs[finding.GetFindingId()] = struct{}{}
   327			findings = append(findings, ReviewFinding{
   328				ID: finding.GetFindingId(), Severity: severity,
   329				Category: finding.GetCategory().String(), Summary: finding.GetSummary(),
   330				EvidenceReferences: finding.GetEvidenceReferences(),
   331			})
   332		}
   333		if hasBlockingFinding && recommendation != ReviewReworkRequired {
   334			return ReviewProposal{}, errors.New("blocking finding requires rework recommendation")
   335		}
   336	
   337		actions := make([]RequiredAction, 0, len(value.GetRequiredActions()))
   338		for _, action := range value.GetRequiredActions() {
   339			if action.GetActionId() == "" || action.GetFindingId() == "" || action.GetDescription() == "" {
   340				return ReviewProposal{}, errors.New("invalid required action")
   341			}
   342			if _, exists := findingIDs[action.GetFindingId()]; !exists {
   343				return ReviewProposal{}, errors.New("required action references unknown finding")
   344			}
   345			actions = append(actions, RequiredAction{
   346				ID: action.GetActionId(), FindingID: action.GetFindingId(),
   347				Description: action.GetDescription(),
   348			})
   349		}
   350		risks := make([]ResidualRisk, 0, len(value.GetResidualRisks()))
   351		for _, risk := range value.GetResidualRisks() {
   352			if risk.GetRiskId() == "" || risk.GetDescription() == "" ||
   353				risk.GetSeverity() == reasoningv1.FindingSeverity_FINDING_SEVERITY_UNSPECIFIED {
   354				return ReviewProposal{}, errors.New("invalid residual risk")
   355			}
   356			risks = append(risks, ResidualRisk{
   357				ID: risk.GetRiskId(), Description: risk.GetDescription(),
   358				Severity: risk.GetSeverity().String(),
   359			})
   360		}
   361		return ReviewProposal{
   362			Recommendation: recommendation, Findings: findings, RequiredActions: actions,
   363			UnrequestedChanges: value.GetUnrequestedChanges(), ResidualRisks: risks,
   364			Assumptions: value.GetAssumptions(),
   365		}, nil
   366	}
